DO $$ BEGIN IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('accounts','account_security','account_security_events','account_terms_acceptances','account_terms_head','account_terms_release_receipts') AND pg_get_userbyid(c.relowner)='console_app') <> 6 THEN RAISE EXCEPTION 'ownership rollback incomplete'; END IF; END $$;
